<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import Session from '$lib/stores/Session';
 import {get} from 'svelte/store';
 import {createAdminClient,canAdmin,AdminError,type AdminClient,type AdminCommand,type AdminContext,type AdminTarget} from './admin-authority-client';
 let client:AdminClient|undefined,epoch=0;
 let account=$state(''),context=$state<AdminContext>(),rows=$state<any[]>([]),target=$state<AdminTarget>(),history=$state<any[]>([]),search=$state(''),next=$state(''),historyNext=$state('');
 let busy=$state(false),error=$state(''),notice=$state(''),needsLogin=$state(false),pending=$state<ReturnType<AdminClient['pending']>>(),saved=$state<AdminCommand>(),review=$state<any>(),receipt=$state<any>();
 let operation=$state<AdminCommand['operation']>('roles'),bundles=$state<string[]>([]),reason=$state(''),replaceCustom=$state(false),ownerRequested=$state(false),ack=$state(false);
 let retryAvailable=$state(false);
 let unsubscribe=()=>{};
 function clear(){epoch++;busy=false;client?.dispose();client=undefined;context=undefined;rows=[];target=undefined;history=[];review=undefined;receipt=undefined;pending=undefined;saved=undefined;retryAvailable=false;reason='';bundles=[];error='';notice='';needsLogin=false;}
 function sync(){if(client){pending=client.pending();saved=client.intent();retryAvailable=client.canRetry();}}
 function fail(e:unknown){error=e instanceof Error?e.message:'This security action could not be completed.';needsLogin=e instanceof AdminError&&(e.code==='session_refresh_required'||e.status===401);try{sync();}catch{error+=' Recovery storage is unavailable; do not repeat the action.';}}
 async function task(fn:()=>Promise<void>){if(busy)return;const mine=epoch;busy=true;error='';try{await fn();}catch(e){if(epoch===mine)fail(e);}finally{if(epoch===mine)busy=false;}}
 async function load(){const mine=epoch;const actor=account;await task(async()=>{client=createAdminClient(actor,()=>{if(epoch!==mine||get(Session)?.identity?.id!==actor)throw new AdminError('The signed-in account changed. No action was replayed.',409);});sync();context=await client.context();if(canAdmin(context,'admin.users.read'))await list();if(canAdmin(context,'admin.audit.read'))await loadHistory();});}
 onMount(()=>{unsubscribe=Session.subscribe(value=>{const current=value?.identity?.id??'';if(current===account)return;clear();account=current;if(account)void load();});if(!account){account=get(Session)?.identity?.id??'';if(account)void load();}});
 onDestroy(()=>{unsubscribe();clear();});
 async function list(after=''){const result=await client!.users(search,after);rows=after?[...rows,...result.data]:result.data;next=result.next??'';}
 async function select(id:string){review=undefined;ack=false;const result=await client!.target(id);target=result.target;bundles=[...target!.bundles];replaceCustom=false;ownerRequested=false;reason='';operation=target!.disabled?'reactivate':'roles';if(canAdmin(context,'admin.audit.read'))await loadHistory(id);}
 async function loadHistory(id=target?.id??'',before=''){const result=await client!.audit(id,before);history=before?[...history,...result.data]:result.data;historyNext=result.next??'';}
 async function resume(){if(!saved)return;const prior=saved;await select(prior.targetId);operation=prior.operation;bundles=[...prior.bundles];reason=prior.reason;replaceCustom=prior.replaceCustom;ownerRequested=prior.ownerRequested;notice='In-memory fields restored for inspection. Check current access, then explicitly review again. No action was replayed.';}
 function grant(){return operation==='roles'?'admin.roles.manage':operation==='revoke-sessions'?'admin.sessions.revoke':operation==='reactivate'?'admin.accounts.manage':'admin.restrictions.manage';}
 async function prepare(){if(!target)return;const command:AdminCommand={requestId:client!.newRequestId(),targetId:target.id,authorityVersion:target.authorityVersion,operation,bundles:operation==='roles'?[...bundles].sort():[],reason,replaceCustom:operation==='roles'&&replaceCustom,ownerRequested:operation==='reactivate'&&ownerRequested};review=await client!.review(command);ack=false;sync();}
 async function confirm(){if(!review||!ack)return;receipt=await client!.confirm(review.command);notice='Security action confirmed. The receipt below is durable.';review=undefined;ack=false;sync();if(receipt.target)target=receipt.target;}
 async function reconcile(){const result=await client!.reconcile();if(result.pending){notice=result.message;}else{receipt=result;review=undefined;notice='The original action is confirmed; it was not repeated.';}sync();}
 function reauthenticate(){clear();window.location.assign('/auth/login?redirect='+encodeURIComponent('/staff/users'));}
 const labels:Record<string,string>={roles:'Change staff access',restrict:'Restrict locally',unrestrict:'Lift local restriction','revoke-sessions':'Sign out native sessions',reactivate:'Reactivate retained account'};
</script>
<svelte:head><title>Users and security · Staff workspace</title></svelte:head>
<main class="admin-workspace">
 <nav aria-label="Staff navigation"><a href="/staff">← Staff workspace</a> <a href="/staff/reports">Report queue</a> <a href="/staff/operations">Operations</a></nav>
 <h1>Users and security</h1>
 <p>Manage this site's native accounts. These controls never grant original-service signing or operator authority.</p>
 {#if !account}<p>Sign in with a native administrator account to continue.</p><a href="/auth/login?redirect=%2Fstaff%2Fusers">Sign in</a>{/if}
 {#if error}<p role="alert" class="error">{error}</p>{/if}
 {#if notice}<p role="status">{notice}</p>{/if}
 {#if needsLogin}<button onclick={reauthenticate}>Sign in again, then start a fresh review</button><p>For privacy, action fields are not saved across navigation. An uncertain request marker remains until checked or cancelled; nothing is replayed.</p>{/if}
 {#if context}<section><h2>Your current access</h2><p>{context.username} · {context.freshAuthentication?'Recent sign-in available':'Sign in again before confirming security changes'}</p><p>{context.roleHierarchy}</p><ul>{#each context.bundles.filter(b=>b.grants.every(g=>context!.permissions.includes(g))) as b}<li>{b.label}</li>{/each}</ul></section>{/if}
 {#if pending}<section class="warning"><h2>Unconfirmed action — do not start a replacement</h2>
 {#if 'blocked' in pending}<p>An older recovery marker is damaged. Its private fields were removed, but the uncertainty fence remains. Do not repeat the action; ask an administrator to inspect security history and resolve the original request. No recovery request can be sent from this marker.</p>
 {:else}<p>Command {pending.requestId}. Only its identifier and fingerprint are stored; private action fields are not saved.</p>
 <button disabled={busy} onclick={()=>task(reconcile)}>Check exact receipt</button>
 {#if retryAvailable}<button disabled={busy} onclick={()=>task(async()=>{receipt=await client!.retryExact();notice='The exact original command is confirmed, with no duplicate effect.';sync();})}>Retry only this unchanged command</button>{/if}
 <button disabled={busy||!pending.commandHash} onclick={()=>task(async()=>{receipt=await client!.settle();notice=receipt.outcome==='cancelled-before-apply'?'The original action is now fenced off without changing the account.':'The original action had already completed; its receipt is shown.';review=undefined;sync();})}>Cancel only if not already applied</button>
 {#if !pending.commandHash}<p>This older marker needs an explicit Check to recover its fingerprint from your server record. A missing record never clears the fence.</p>{/if}
 <p>After leaving this view, exact retry is unavailable. Check or cancel this request, then select the account and make a fresh review.</p>{/if}</section>{/if}
 {#if saved&&!pending}<section><h2>Unsubmitted fields in this view</h2><p>{labels[saved.operation]} for {saved.targetId}. These private fields stay in memory only. Resume is read-only; leaving or signing out discards them.</p><button disabled={busy||!canAdmin(context,'admin.users.read')} onclick={()=>task(resume)}>Resume in-memory fields</button><button disabled={busy} onclick={()=>{client!.cancel();review=undefined;sync();}}>Discard unsent review</button></section>{/if}
 {#if canAdmin(context,'admin.users.read')}<section><h2>Find an account</h2><form onsubmit={e=>{e.preventDefault();void task(()=>list());}}><label>Username or exact account ID <input bind:value={search} maxlength="100" /></label><button disabled={busy}>Search users</button></form>
 <ul>{#each rows as row}<li><button disabled={busy} onclick={()=>task(()=>select(row.id))}>{row.username}</button> <small>{row.id} · {row.verified?'Verified':'Unverified'}{row.disabled?' · Disabled':''}{row.restricted?' · Restricted':''}</small></li>{/each}</ul>{#if next}<button disabled={busy} onclick={()=>task(()=>list(next))}>More accounts</button>{/if}</section>{/if}
 {#if target}<section><h2>{target.username}</h2><p>Exact native account: <code>{target.id}</code> · Authority revision {target.authorityVersion}</p><p>{target.verified?'Verified':'Unverified'} · {target.disabled?'Disabled':'Enabled'} · {target.restricted?'Locally restricted':'No local restriction'}</p>
 <details><summary>Current exact roles and permissions</summary><p>Roles: {target.roles.join(', ')}</p><ul>{#each target.permissions as permission}<li><code>{permission}</code></li>{/each}</ul></details>
 <form onsubmit={e=>{e.preventDefault();void task(prepare);}}>
 <label>Action <select bind:value={operation} onchange={()=>{review=undefined;ack=false;}}>
 {#if canAdmin(context,'admin.roles.manage')}<option value="roles">Change staff access</option>{/if}
 {#if canAdmin(context,'admin.restrictions.manage')}<option value="restrict">Restrict locally until explicitly lifted</option><option value="unrestrict">Lift local restriction / ban</option>{/if}
 {#if canAdmin(context,'admin.sessions.revoke')}<option value="revoke-sessions">Sign out this account's native sessions</option>{/if}
 {#if canAdmin(context,'admin.accounts.manage')&&target.disabled&&target.retainedAccount}<option value="reactivate">Reactivate this retained account</option>{/if}
 </select></label>
 {#if operation==='roles'}<fieldset disabled={busy||!!pending}><legend>Staff access bundles</legend><p>Unchecked bundles are removed. Normal account permissions and independent restrictions are preserved.</p>{#each context?.bundles??[] as bundle}<label class="bundle"><input type="checkbox" value={bundle.id} bind:group={bundles} onchange={()=>review=undefined} />{bundle.label}<details><summary>Exact scope</summary><p>Roles: {bundle.roles.join(', ')}. Grants: {bundle.grants.join(', ')}.</p></details></label>{/each}</fieldset>
 {#if target.customAuthority}<p class="warning">This account has legacy/custom access. The review will show every role and grant removed or added; this is not a partial merge.</p><label><input type="checkbox" bind:checked={replaceCustom} onchange={()=>{review=undefined;ack=false;}} /> I want to replace the displayed legacy/custom access with these bundles.</label>{/if}{/if}
 {#if operation==='reactivate'}<p>Only a retained, owner-disabled account can be re-enabled. Old sessions, API credentials and identity links stay revoked. No verification or independent ban is cleared.</p><label><input type="checkbox" bind:checked={ownerRequested} onchange={()=>{review=undefined;ack=false;}} /> The account owner requested reactivation.</label>{/if}
 <label>Reason (no passwords, tokens or private contact details)<textarea bind:value={reason} maxlength="500" required oninput={()=>review=undefined}></textarea></label>
 <button disabled={busy||!!pending||!canAdmin(context,grant())||!reason.trim()||(operation==='roles'&&target.customAuthority&&!replaceCustom)||(operation==='reactivate'&&!ownerRequested)}>Review exact effect</button>
 </form></section>{/if}
 {#if review}<section class="review"><h2>Review before confirming</h2><p><strong>{review.before.username}</strong> · {review.before.id} · revision {review.before.authorityVersion}</p><p>{review.effect}</p><p>Reason: {review.command.reason}</p><p>Roles added: {review.roleChanges.added.join(', ')||'None'}. Roles removed: {review.roleChanges.removed.join(', ')||'None'}.</p><details open><summary>Exact permission changes</summary><p>Added: {review.permissionChanges.added.join(', ')||'None'}</p><p>Removed: {review.permissionChanges.removed.join(', ')||'None'}</p></details>
 <label><input type="checkbox" bind:checked={ack} /> I reviewed this exact account, scope and change.</label><button disabled={busy||!ack||!!pending} onclick={()=>task(confirm)}>Confirm {labels[review.command.operation]}</button><button disabled={busy} onclick={()=>{review=undefined;ack=false;}}>Back to editing</button>{#if !review.freshAuthentication}<button onclick={reauthenticate}>Sign in again before confirming</button>{/if}</section>{/if}
 {#if receipt}<section role="status"><h2>Confirmed receipt</h2><p>{labels[receipt.operation]} · {receipt.targetId}</p><p>Command {receipt.requestId} · authority revision {receipt.authorityVersion}{receipt.auditId?` · audit entry ${receipt.auditId}`:''}.</p><p>{receipt.outcome==='cancelled-before-apply'?'Cancelled before applying. A late request cannot change this account.':receipt.changed?'The reviewed local change was applied.':'No authority change was needed; the action is recorded.'}</p>{#if receipt.effects?.ordinarySessions!==undefined}<p>Revoked {receipt.effects.ordinarySessions} ordinary sessions, {receipt.effects.recoverySessions} recovery sessions, {receipt.effects.apiCredentials} API credentials and {receipt.effects.pendingRecoveryLinks} pending recovery links.</p>{/if}</section>{/if}
 {#if canAdmin(context,'admin.audit.read')}<section><h2>Security history {target?`for ${target.username}`:''}</h2><button disabled={busy} onclick={()=>task(()=>loadHistory())}>Refresh security history</button>{#if target}<button disabled={busy} onclick={()=>task(()=>loadHistory(''))}>All accounts</button>{/if}<ol>{#each history as entry}<li><strong>{entry.operation}</strong> · {entry.targetId} · {entry.createdAt}<p>{entry.reason}</p><p>Actor: {entry.actorId??'Explicit offline bootstrap'} · audit {entry.id} · authority {entry.before.authorityVersion} → {entry.after.authorityVersion}</p></li>{/each}</ol>{#if historyNext}<button disabled={busy} onclick={()=>task(()=>loadHistory(target?.id??'',historyNext))}>Earlier history</button>{/if}</section>{/if}
</main>
<style>
 .admin-workspace{max-width:72rem;margin:0 auto;padding:1.5rem;display:grid;gap:1rem}.admin-workspace section{border:1px solid #8886;border-radius:.5rem;padding:1rem}.admin-workspace nav{display:flex;gap:1rem;flex-wrap:wrap}.admin-workspace h1{font-size:1.8rem;font-weight:700}.admin-workspace h2{font-size:1.25rem;font-weight:600}.admin-workspace label{display:block;margin:.6rem 0}.admin-workspace input:not([type=checkbox]),.admin-workspace textarea,.admin-workspace select{display:block;width:100%;padding:.5rem;border:1px solid #8888;border-radius:.25rem;background:transparent}.admin-workspace button{border:1px solid #8888;padding:.45rem .7rem;margin:.25rem;border-radius:.3rem}.admin-workspace button:disabled{opacity:.5}.admin-workspace ul,.admin-workspace ol{padding-left:1.3rem;list-style:revert}.admin-workspace li{margin:.4rem 0}.admin-workspace p{margin:.5rem 0;overflow-wrap:anywhere}.admin-workspace details{margin:.5rem 0}.admin-workspace .error{border-left:4px solid #c44;padding:.7rem}.admin-workspace .warning{border-left:4px solid #d90;padding:.7rem}.admin-workspace .review{border:2px solid #68a}.admin-workspace .bundle{padding:.4rem;border-bottom:1px solid #8883}.admin-workspace small{overflow-wrap:anywhere}
</style>
